import { test, expect } from '@playwright/test';

test.describe('File Upload - Unsupported File Type Error', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/file-upload');
  });

  test('should display error message when uploading an unsupported file type', async ({ page }) => {
    // Setup: intercept the upload API call
    await page.route('**/api/upload', (route) => {
      route.abort('failed');
    });

    // Setup: intercept the error response
    await page.route('**/api/upload', (route) => {
      route.continue({
        status: 400,
        body: JSON.stringify({ error: 'Unsupported file type. Only PDF and DOCX are allowed.' }),
      });
    });

    // Action: select an unsupported file
    const fileInput = page.getByLabel('Upload file');
    await fileInput.setInputFiles('fixtures/unsupported-file.pdf');

    // Action: click upload button
    const uploadButton = page.getByRole('button', { name: /upload/i });
    await uploadButton.click();

    // Wait for error message to appear
    await page.waitForTimeout(500);

    // Assertion: verify error message is displayed
    const errorMessage = page.getByText(/Unsupported file type/i);
    await expect(errorMessage).toBeVisible();

    // Assertion: verify error message contains specific details
    await expect(errorMessage).toContainText('Only PDF and DOCX are allowed.');

    // Assertion: verify upload success message does not appear
    const successMessage = page.getByText(/File uploaded successfully/i);
    await expect(successMessage).not.toBeVisible();
  });

  test('should allow upload of supported file type and clear error message', async ({ page }) => {
    // Setup: intercept the upload API call
    await page.route('**/api/upload', (route) => {
      route.continue({
        status: 200,
        body: JSON.stringify({ success: true, message: 'File uploaded successfully' }),
      });
    });

    // Action: select a supported file
    const fileInput = page.getByLabel('Upload file');
    await fileInput.setInputFiles('fixtures/supported-document.pdf');

    // Action: click upload button
    const uploadButton = page.getByRole('button', { name: /upload/i });
    await uploadButton.click();

    // Wait for success response
    await page.waitForTimeout(500);

    // Assertion: verify success message is displayed
    const successMessage = page.getByText(/File uploaded successfully/i);
    await expect(successMessage).toBeVisible();

    // Assertion: verify error message is not visible
    const errorMessage = page.getByText(/Unsupported file type/i);
    await expect(errorMessage).not.toBeVisible();

    // Assertion: verify file name is displayed
    const fileNameDisplay = page.getByText('supported-document.pdf');
    await expect(fileNameDisplay).toBeVisible();
  });
});
